 // Element scenes use numeric changes as a reason to inspect evidence, never
 // as proof of a content/configuration defect. The two evidence categories are
 // exclusive per object; a higher-priority category wins when both are found.
 const element = (name, relationship, cue, evidence, first, second, missing = []) => {
  const cases = [first,second];
  put(name,[relationship,'数值变化只决定核查优先级；只有同对象素材／配置与结果链路对齐后才能确认具体问题。'],
   '定位对象及版本 → 核对配置或素材 → 关联同对象指标 → 分类确认问题 → 单变量调整与复核',
   cases.map((c,index)=>issue(c[0],c[1],cue,c[2],c[3],{
    blocked:true, evidenceCategory:index===0?'primary_defect':'secondary_defect',
    confirmationRule:c[4]+(index===1?'；且不存在本场景第一优先缺陷。':''),
    evidenceChecks:[evidence,c[4],'同对象调整前后样本及来源可比；样本不足时只输出待核查'],
    missing:[evidence,...missing],exclusiveGroup:'object_defect',
   })),missing,'仅确认本要素问题；同一对象先处理第一优先缺陷，不与父级环节重复计损。');
  profiles[name].requiredEvidence=[name+'对应的原始素材或配置、对象ID及版本时间',evidence,'同商家同周期同来源的对象级指标、样本和对照记录'];
 };
